import math

state = {
    'head_timer': 0.0,
    'head_phase': 0,
}

def control(obs):
    dt = obs['dt']
    hitch = obs['hitch_deg']

    target_speed = -0.85

    state['head_timer'] += dt
    if state['head_timer'] > 1.2:
        state['head_timer'] = 0.0
        state['head_phase'] = (state['head_phase'] + 1) % 4

    gazes = [64.0, 160.0, -64.0, -160.0]
    target_gaze = gazes[state['head_phase']]

    left_clearance = 999.0
    right_clearance = 999.0

    for vname, view in obs.get('views', {}).items():
        ox, oy = view['origin']
        for b_deg, d_m in view.get('walls', []):
            b_rad = math.radians(b_deg)
            px = ox + d_m * math.cos(b_rad)
            py = oy + d_m * math.sin(b_rad)
            if -8.0 <= px <= 2.5:
                if py > 0:
                    left_clearance = min(left_clearance, py)
                else:
                    right_clearance = min(right_clearance, -py)

    lat_err = 0.0
    if left_clearance < 900 and right_clearance < 900:
        lat_err = (left_clearance - right_clearance) / 2.0
    elif left_clearance < 900:
        lat_err = left_clearance - 1.8
    elif right_clearance < 900:
        lat_err = 1.8 - right_clearance

    target_hitch = max(-18.0, min(18.0, lat_err * 12.0))

    hitch_err = hitch - target_hitch
    target_steer = max(-35.0, min(35.0, hitch_err * 2.8))

    if obs['status'] in ('JACKKNIFED', 'PINNED'):
        target_speed = 1.2
        target_steer = -hitch * 0.8

    return (target_steer, target_speed, target_gaze)

